// Writes apps/desktop_ui/web/theme.css from the palette registry.
//
//   dart run conduit_theme:generate_theme_css [output-path]
//
// The output is git-ignored and regenerated by the desktop build, so a stale
// checkout can never ship last week's colours.
import 'dart:io';

import 'package:conduit_theme/conduit_theme.dart';
import 'package:path/path.dart' as p;

void main(List<String> args) {
  final target = args.isNotEmpty
      ? args.first
      : p.join('apps', 'desktop_ui', 'web', 'theme.css');
  final file = File(target);
  file.parent.createSync(recursive: true);
  file.writeAsStringSync(generateThemeCss());
  stdout.writeln(
    'Wrote ${kDesktopPalettes.length} palettes to ${file.path} '
    '(${file.lengthSync()} bytes)',
  );
}
